#!/usr/bin/env python3
"""Report evidence without promoting assistant/proxy checks to human validation."""
import json,csv,sys,hashlib,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'));sys.path.insert(0,str(ROOT/'Model'))
from export_precision_blind_holdout import EXCLUSIONS,excluded_queries
from product_ontology import norm
from human_qa_ingredient_matcher import immutable_hash
OUT=ROOT/'data/matcher_precision_hardening';HOLD=ROOT/'data/matcher_final_200_holdout'
def main():
 before=json.loads((OUT/'before_evaluation.json').read_text());after=json.loads((OUT/'after_evaluation.json').read_text());diag=json.loads((OUT/'micro_diagnostics.json').read_text());causes=json.loads((OUT/'root_causes.json').read_text());tests=json.loads((OUT/'separate_test_results.json').read_text());corpus=json.loads((OUT/'corpus_checks.json').read_text());sample=json.loads((HOLD/'sample.json').read_text());rows=list(csv.DictReader((HOLD/'review.csv').open()))
 keys={norm(r['ingredient_query']) for r in rows};assert len(rows)==len(keys)==200
 overlaps={p:len(keys & excluded_queries(ROOT/p)) for p in EXCLUSIONS};assert not any(overlaps.values());assert all(not r['review_label'] for r in rows)
 assert all(immutable_hash(r)==sample['immutable_review_hashes'][r['case_id']] for r in rows)
 assert hashlib.sha256((HOLD/'review.csv').read_bytes()).hexdigest()==sample['review_csv_sha256']
 assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in sample['source_hashes'].items())
 assert hashlib.sha256((HOLD/'population.jsonl').read_bytes()).hexdigest()==sample['population_sha256']
 source_hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sample['source_hashes']}
 (OUT/'source_hashes_after.json').write_text(json.dumps(source_hashes,indent=2)+'\n')
 populations={t:{r['case_id']:r for r in map(json.loads,(OUT/(t+'_population.jsonl')).open())} for t in ('before','after')}
 strong={}
 for name in ('cheese','meat','broth','milk','yogurt','tomato'):
  cohort=[r for r in populations['before'].values() if r['ontology'].get('family')==name or name in ('milk','yogurt') and r['ontology'].get('family')=='dairy' and name in (r['ontology'].get('subfamily') or '')]
  def pid(r):return (r['selected_match'] or {}).get('product_id')
  strong[name]={'queries':len(cohort),'changed_selections':sum(pid(r)!=pid(populations['after'][r['case_id']]) for r in cohort),'accepted_before':sum(bool(pid(r)) for r in cohort),'accepted_after':sum(bool(pid(populations['after'][r['case_id']])) for r in cohort)}
 domains=collections.Counter((r['selected_match']['ontology'].get('domain') or 'food') for r in populations['after'].values() if r['selected_match'])
 gate=diag['diagnostic_counts']['WRONG'].get('corrected',0)+diag['diagnostic_counts']['WRONG'].get('abstained',0)>=20 and not corpus['failures'] and all(r['passed'] for r in tests.values())
 assert gate
 report={'recommendation':'READY_FOR_FINAL_200_CASE_REVIEW','independent_human_metrics':{'exact_high_precision':None,'medium_precision':None,'false_positive_rate':None,'false_negative_rate':None,'wrong_family_count':None,'prepared_food_false_positives':None,'cheese_accuracy':None,'meat_cut_accuracy':None},'reason':'Fresh blind review is pending. Assistant reused-sample diagnostics and name-rule proxies do not certify population accuracy.','diagnostic_counts':diag['diagnostic_counts'],'population_before':{k:before[k] for k in ('population_count','accepted','rejected','no_match_rate','confidence_distribution','latency')},'population_after':{k:after[k] for k in ('population_count','accepted','rejected','no_match_rate','confidence_distribution','latency')},'proxy_before':before['top1_name_rule_proxy'],'proxy_after':after['top1_name_rule_proxy'],'candidate_recall_original_52_proxy':after['candidate_recall_proxy'],'candidate_recall_recovered_7_diagnostic':diag['known_valid_candidate_recall'],'strong_category_cohorts':strong,'accepted_classified_domains':dict(domains),'tests':{'full':502,'separate':tests,'corpus':corpus},'blind_holdout':{'path':str(HOLD/'review.csv'),'count':len(rows),'seed':sample['seed'],'counts':sample['sample_counts'],'availability':sample['hard_available_counts'],'scarcity':sample['hard_quota_shortfalls_before_redistribution'],'independently_recomputed_overlaps':overlaps,'blank_labels':True,'source_hashes_verified':True},'limitations':['Query normalization retains quantities; food concepts may recur despite query disjointness.','One changed lemon selection has a truncated product head and remains unresolved.','Sweet cherry candidate state is undocumented; no explicit purchased-state request, structurally supported only.','Candidate recall over recovered products is a selected diagnostic subset, not recall over all 58 false negatives.','Explicit domain/SNAP metadata gates do not certify missing product-domain metadata.','Proxy includes 146 ambiguous/unlabelled selected products and uses frozen name rules.']}
 (OUT/'report.json').write_text(json.dumps(report,indent=2)+'\n')
 pct=lambda x:f'{100*x:.2f}%'
 lines=['# Precision-first hardening report','', 'READY_FOR_FINAL_200_CASE_REVIEW. This is readiness for blind review, not a freeze recommendation. No independent human precision is available. The reused 300-case assistant review is intentionally hard-biased; ambiguous/unresolved cases are never counted as correct.','', '## Root causes and general fixes','', '| Root cause | Prior wrong cases |','|---|---:|']
 lines += [f'| {k} | {v} |' for k,v in causes['wrong_root_cause_counts'].items()]
 lines += ['', 'All 22 diagnoses were frozen before production edits in `root_causes.json`, `wrong_root_causes.csv`, source snapshots and `source_hashes_before.json`.','', 'General changes in `Model/food_identity_rules.py` and `Model/product_ontology.py`: purchased product heads outrank component/flavor tokens; basic ingredients reject derived products; explicit nonfood/alcohol/ineligibility evidence hard-vetoes acceptance; one reusable required-variant comparison verifies bran, whole wheat, long/white grain, sweet/dill pickle and center-cut identity; red/mixed potatoes and sweet/tart cherries stay distinct; preserved produce does not satisfy an untreated produce request; raw ham, fried meat, imitation toppings and bacon lardons retain separate forms; specified vegetable mixtures and headings/compound lines abstain. Pine nuts, raspberry vinegar, sweet relish, sardines, egg noodles, tofu, cocoa, vanilla, lima beans and marjoram receive general taxonomy/alias identities.','', 'Replacement checks additionally exposed cream-flavored candy, mixed potato varieties, preserved lemons and fruit-flavored nuts. Their general heads/attributes now have synthetic regression witnesses. The 66-cell ingredient-by-derivative matrix and legitimate prepared identities remain covered. No ID, brand, recipe or query/product pair appears as a production exception.','', 'Embedding/ranking weights, confidence thresholds and material-identity margin gates were preserved. Retrieval source is byte-identical to the pre-pass snapshot; compatibility source changed only its version. Ontology, compatibility and manifest versions are v3.3. Cheese, species/cuts, broth, dairy/plant identity, yogurt and tomato boundaries remain structural vetoes.','', '## Reused 300-case diagnostics','', f"Prior 22 WRONG: **{diag['diagnostic_counts']['WRONG'].get('corrected',0)} corrected/acceptable, {diag['diagnostic_counts']['WRONG'].get('abstained',0)} abstained, 0 confirmed remaining original wrong products, {diag['diagnostic_counts']['WRONG'].get('unresolved',0)} unresolved replacement**. The unresolved replacement is not counted as corrected. Thus 21/22 meet the stopping gate.",'', 'Prior 58 SHOULD_HAVE_MATCHED: **7 recovered, 51 still rejected, 0 newly wrong among these 58**. Each recovered selection was inspected against its requested identity, not inferred from a proxy score. Original review files were preserved. All 300 queries were replayed with semantic retrieval enabled and agreed with the final population selections. Changed outputs on this trained-on sample are diagnostics only.','', '| Case | Original query | Current product | Outcome | Evidence / handling |','|---|---|---|---|---|']
 esc=lambda s:str(s or '').replace('|','/').replace('\n',' ')
 for r in diag['rows']:
  if r['original_review_label'] in ('WRONG','SHOULD_HAVE_MATCHED'):
   note=r['assistant_diagnostic_note'] or ('Safe structural/margin abstention; no recall relaxation.' if not r['current_selected_product'] else 'Unresolved; not counted as correct.')
   lines.append('| '+' | '.join(esc(v) for v in (r['case_id'],r['ingredient_query'],r['current_selected_product'] or 'NONE',r['diagnostic_outcome'],note))+' |')
 lines += ['', 'The lemon replacement is `Pepperidge Farm Lemon Frozen`: its name and feature record omit the actual purchased head. This is a remaining product-normalization/metadata limitation. It was not “fixed” with a brand rule and must not be treated as a correct lemon selection. Sweet cherries verify the requested sweet variety; missing state is disclosed, with no fresh-state claim.','', 'Recovered stages: tofu, vanilla, cocoa and lima beans—ONTOLOGY/alias; egg noodles, whole-wheat pasta and cooked pasta—COMPATIBILITY/cooking preparation. No global recall/threshold relaxation.','', '## Population and proxy comparison','', '| Measure | Before | After |','|---|---:|---:|',f"| Real queries | {before['population_count']} | {after['population_count']} |",f"| Accepted | {before['accepted']} | {after['accepted']} |",f"| Rejected | {before['rejected']} | {after['rejected']} |",f"| No match | {pct(before['no_match_rate'])} | {pct(after['no_match_rate'])} |"]
 for k,title in [('precision_proxy','Name-rule precision proxy'),('recall_proxy','Name-rule recall proxy'),('false_positive_rate_proxy','Name-rule false-positive rate proxy'),('false_negative_rate_proxy','Name-rule false-negative rate proxy'),('precision_including_unlabelled_as_not_correct_proxy','Precision proxy with unlabelled counted non-correct')]:lines.append(f"| {title} | {pct(before['top1_name_rule_proxy']['all'][k])} | {pct(after['top1_name_rule_proxy']['all'][k])} |")
 for k,title in [('wrong_family_count','Name-rule wrong-family count'),('prepared_food_fp','Name-rule prepared-food FP'),('ambiguous_or_unlabelled_product','Unlabelled/ambiguous selected products')]:lines.append(f"| {title} | {before['top1_name_rule_proxy']['all'][k]} | {after['top1_name_rule_proxy']['all'][k]} |")
 for k,title in [('warm_uncached_median_ms','Warm median ms'),('warm_uncached_p95_ms','Warm p95 ms')]:lines.append(f"| {title} | {before['latency'][k]:.3f} | {after['latency'][k]:.3f} |")
 lines += ['', f"Confidence after: `{json.dumps(after['confidence_distribution'])}`. No-match remains below 33%; it was not optimized as a target. Latency method: {after['latency_method']}.", '', 'The one additional proxy wrong-family is `lemon sorbet or whipped cream`: the fixed name-rule answer treats it as lemon only; the current product is Organic Valley Organic Heavy Whipping Cream, satisfying the explicit cream alternative. The previous product was strawberry cream sour belts. This explains the proxy drop; no proxy labels were altered. Do not interpret these frozen name rules as perfect gold.','', 'Human Exact/High and Medium precision, human FP/FN rates, human wrong-family/prepared-food counts, cheese and meat/cut accuracy remain **unmeasured** until fresh review. Proxy category figures remain in report.json; no assistant precision is presented as human precision.','', 'Candidate recall@5/10/20: **100%/100%/100% on seven inspected recovered-product references** (a recovered subset, not all 58). Original 52 assistant-suggested references: **86.54%/86.54%/86.54%**, including seven uncertain-state references. Both measures are diagnostic and reported separately. Failure stages and product IDs are in micro_diagnostics.json and after_evaluation.json.','', '## Strong categories and tests','', '| Existing population cohort | Queries | Changed product decisions | Accepted before / after |','|---|---:|---:|---|']
 for k,v in strong.items():lines.append(f"| {k} | {v['queries']} | {v['changed_selections']} | {v['accepted_before']} / {v['accepted_after']} |")
 lines += ['', 'These counts measure decision stability, not accuracy. Every accepted output is classified food by the current ontology; this does not prove unrecognized/truncated products are food.','', '**Full suite: 502/502 passing. Regression corpus: 2,042/2,042 expectations pass**, including opt-in substitute expectations. 27 new records anchor all 22 old wrong pairs and five direct recoveries; seven new test methods contain additional class witnesses, the 66-cell derivative matrix, nine flavor/nut head traps and explicit-white-grain checks. Zero newly accepted negative regression cases.','', '| Separate suite | Tests | Result |','|---|---:|---|']
 lines += [f"| {k} | {v['tests']} | PASS |" for k,v in tests.items()]
 lines += ['', '## Fresh blind review artifact','', '`data/matcher_final_200_holdout/review.csv`: **200 cases**, seed **20261013**, 100 accepted Exact/High, 50 rejected and 50 hard. Labels and review fields are blank. Top alternatives, score breakdowns, query/product ontology and current decisions are included.','', '| Stratum | Requested | Sampled | Available before competing quotas |','|---|---:|---:|---:|']
 for k,v in sample['sample_counts'].items():lines.append(f"| {k} | {v['requested']} | {v['sampled']} | {sample['hard_available_counts'].get(k[6:],'—')} |")
 lines += ['', f"Scarcity before redistribution: `{json.dumps(sample['hard_quota_shortfalls_before_redistribution'])}`. Hard categories describe actual query risk, not synthetic inserted inventory products; nonfood traps are additionally covered by synthetic regressions.",'', 'An independent recomputation verified zero normalized-query overlap against all four previous QA sets (950/1100/700/300), all five regression corpora, real-recipe regression cases, harvested historical ingredients and the inventory benchmark. CSV immutable-field hashes, source hashes, population snapshot and blank labels were verified. Normalization retains quantities: different lines can share a food concept; this is query disjointness, not canonical-food independence. The sample is fixed without considering review correctness.','', 'Review with `.venv/bin/python scripts/review_matcher_human.py --directory data/matcher_final_200_holdout`. `sample.json` freezes selection, source hashes and exclusion manifest. The README explains the review workflow.','', 'Existing unrelated working-tree changes were preserved. No Recipe Chat/search/frontend/scheduling/shopping code was edited in this pass; no staging, commit, push, stash, restore or revert was performed.','', '`git diff --check` passed after the completed pass. No Git staging or publication was performed.','', '**READY_FOR_FINAL_200_CASE_REVIEW**','']
 (OUT/'report.md').write_text('\n'.join(lines))
 print(json.dumps({'recommendation':report['recommendation'],'diagnostics':report['diagnostic_counts'],'blind_holdout_counts':sample['sample_counts'],'overlaps':overlaps,'strong_categories':strong},indent=2))
if __name__=='__main__':main()
